// ===== Auxiliar (o "revelar letra" da forca) =====
function updateAssistBtn() {
    revealBtn.disabled = !state.active || state.assistUsed || safeCandidates().length === 0;
}

function assistReveal() {
    if (!state.active || state.assistUsed) return;
    const options = safeCandidates();
    if (options.length === 0) return;
    state.assistUsed = true;
    const [r, c] = options[Math.floor(Math.random() * options.length)];
    state.board[r][c].hinted = false;
    floodReveal(r, c);
    updateOpened();
    playWrong();
    messageElSoft('Célula revelada custando 5 segundos.');
    if (state.mode === 'duel' && state.timerId) {
        state.timeLeft = Math.max(0, state.timeLeft - 5);
        renderTimer();
    }
    renderBoard();
    renderStats();
    updateFace();
    if (state.opened >= state.safeTotal) { endRound(true, state.currentTurn); return; }
    updateAssistBtn();
}

