// ===== Herói =====
function makeHero() {
    const b = CFG.hero.base;
    return {
        level: 1,
        xp: 0,
        xpNeeded: CFG.xpForLevel(1),
        forca: b.forca,
        agil: b.agil,
        vida: b.vida,
        int: b.int,
        gold: 0,
        kills: 0,
        hp: 0,
        equip: { arma: null, armadura: null, elmo: null, colar: null },
        inv: []
    };
}

function equipBonus(stat) {
    const h = state.hero;
    let total = 0;
    Object.keys(h.equip).forEach(slotId => {
        const item = h.equip[slotId];
        if (item && item.bonus[stat]) total += item.bonus[stat];
    });
    return total;
}

function heroForca() { return state.hero.forca + equipBonus('forca'); }
function heroAgil()  { return state.hero.agil + equipBonus('agil'); }
function heroVida()  { return state.hero.vida + equipBonus('vida'); }
function heroInt()   { return state.hero.int + equipBonus('int'); }

function heroMaxHp() { return CFG.maxHp(heroVida()); }

function heroFisBase() { return Math.round(heroForca() * 0.9) + equipBonus('fis'); }
function heroArcBase() { return Math.round(heroInt() * 0.7) + equipBonus('arc'); }
function heroDefense() { return equipBonus('def'); }

function heroCritChance() {
    return Math.min(CFG.crit.cap, CFG.crit.base + heroAgil() * CFG.crit.perAgil);
}

function heroDodgeChance() {
    return Math.min(CFG.dodge.cap, heroAgil() * CFG.dodge.perAgil);
}

function heroAttackRoll() {
    const fis = Math.max(1, Math.round(heroFisBase() * (0.9 + Math.random() * 0.2)));
    const arc = Math.max(0, Math.round(heroArcBase() * (0.9 + Math.random() * 0.2)));
    const isCrit = Math.random() < heroCritChance();
    const mult = isCrit ? CFG.crit.mult : 1;
    return { fis: Math.round(fis * mult), arc: Math.round(arc * mult), isCrit: isCrit };
}

function heroLevelUp() {
    const h = state.hero;
    h.level += 1;
    h.forca += CFG.hero.perLevel.forca;
    h.agil += CFG.hero.perLevel.agil;
    h.vida += CFG.hero.perLevel.vida;
    h.int += CFG.hero.perLevel.int;
    h.xp -= h.xpNeeded;
    h.xpNeeded = CFG.xpForLevel(h.level);
    h.hp = heroMaxHp();
}

function heroGainXp(amount) {
    const h = state.hero;
    h.xp += amount;
    let ups = 0;
    while (h.xp >= h.xpNeeded && ups < 60) {
        heroLevelUp();
        ups += 1;
    }
    return ups;
}

