// ===== Combate idle =====
function stopTimers() {
    if (state.heroTimer) clearInterval(state.heroTimer);
    if (state.enemyTimer) clearInterval(state.enemyTimer);
    state.heroTimer = null;
    state.enemyTimer = null;
}

function startBattle() {
    stopTimers();
    state.over = false;
    state.heroTimer = setInterval(heroTurn, CFG.heroAtkMs);
    state.enemyTimer = setInterval(enemyTurn, CFG.enemyAtkMs);
}

function runTitle() {
    return randomPick(NAME_PREFIX) + ' ' + randomPick(NAME_SUFFIX);
}

function heroTurn() {
    if (state.over || !state.enemy) return;
    const e = state.enemy;
    const roll = heroAttackRoll();
    const fis = Math.max(0, Math.round(roll.fis * (1 - e.res.fis / 100)));
    const arc = Math.max(0, Math.round(roll.arc * (1 - e.res.arc / 100)));
    const total = Math.max(1, fis + arc);
    e.hp -= total;
    floatDamage('enemy', '-' + total, roll.isCrit ? 'crit' : 'fis');

    let msg = 'O Herói golpeia ' + e.name + ': ' + fis + ' físico' + (arc ? ' + ' + arc + ' arcano' : '') + '.';
    if (roll.isCrit) msg = 'CRÍTICO! ' + msg;
    if (roll.arc > 0 && arc === 0) msg += ' (arcano resistido)';
    logMsg(msg, roll.isCrit ? 'lvl' : '');

    if (e.hp <= 0) { enemyDefeated(); return; }
    renderAll();
}

function enemyTurn() {
    if (state.over || !state.enemy) return;
    const e = state.enemy;
    if (Math.random() < heroDodgeChance()) {
        floatDamage('hero', 'esquiva', 'dodge');
        logMsg('O Herói esquivou do ataque de ' + e.name + '!', 'good');
        renderAll();
        return;
    }
    const raw = Math.max(1, Math.round(e.dmg * (0.85 + Math.random() * 0.3)));
    const dmg = Math.max(1, raw - heroDefense());
    state.hero.hp -= dmg;
    floatDamage('hero', '-' + dmg, '');
    const elementType = CFG.dmgTypes[e.el].label.toLowerCase();
    let msg = e.name + ' atinge o Herói em ' + dmg + ' dano ' + elementType + '.';
    if (e.el === 'nec') {
        const drain = Math.round(dmg * 0.25);
        if (drain > 0 && e.hp < e.maxHp) {
            e.hp = Math.min(e.maxHp, e.hp + drain);
            msg += ' Drena ' + drain + ' de vida!';
        }
    }
    logMsg(msg, 'bad');
    if (state.hero.hp <= 0) { heroDeath(); return; }
    renderAll();
}

function enemyDefeated() {
    const e = state.enemy;
    const h = state.hero;
    h.gold += e.gold;
    h.kills += 1;
    logMsg(e.name + (e.boss ? ' (BOSS)' : '') + ' foi derrotado! +' + e.xp + ' XP, +' + e.gold + ' ouro.', 'good');

    const ups = heroGainXp(e.xp);
    if (ups > 0) logMsg('O Herói subiu para o nível ' + h.level + '!', 'lvl');

    const drop = rollDrop(e, h.level);
    if (drop) {
        h.inv.push(drop);
        enforceInvLimit();
        state.uiDirty = true;
        logMsg('Drop: ' + drop.name + ' (' + CFG.tierNames[drop.tier] + (e.boss ? ', bônus +50%' : '') + ')', 'drop');
    }

    if (e.boss) {
        state.stage += 1;
        logMsg('🔓 Boss derrotado! Nível ' + state.stage + ' desbloqueado — as criaturas passam a ser mais fortes.', 'lvl');
    } else {
        state.bossIn = Math.max(0, state.bossIn - 1);
    }
    spawnEnemy();
    logMsg('Uma nova criatura se aproxima: ' + state.enemy.name + '.', '');
    renderAll();
}

function heroDeath() {
    state.over = true;
    stopTimers();
    state.hero.hp = 0;
    logMsg('O Herói caiu em batalha...', 'bad');
    renderAll();
    deathOverlay.classList.add('show');
    startAutoRevive();
}

// ===== Levantar automático após 3s =====
function startAutoRevive() {
    clearAutoRevive();
    const total = Math.ceil(CFG.autoReviveMs / 1000);
    autoReviveNote.hidden = false;
    const updateNote = (left) => {
        autoReviveNote.textContent = 'Levantando automaticamente em ' + left + 's… (ou clique no botão para levantar agora)';
    };
    updateNote(total);
    const started = Date.now();
    state.autoReviveTimer = setTimeout(() => {
        state.autoReviveTimer = null;
        if (state.over) revive();
    }, CFG.autoReviveMs);
    state.autoReviveCountTimer = setInterval(() => {
        updateNote(Math.max(0, Math.ceil((CFG.autoReviveMs - (Date.now() - started)) / 1000)));
    }, 200);
}

function clearAutoRevive() {
    if (state.autoReviveTimer) { clearTimeout(state.autoReviveTimer); state.autoReviveTimer = null; }
    if (state.autoReviveCountTimer) { clearInterval(state.autoReviveCountTimer); state.autoReviveCountTimer = null; }
}

function revive() {
    clearAutoRevive();
    autoReviveNote.hidden = true;
    state.runs += 1;
    const h = state.hero;
    h.gold = 0;
    h.kills = 0;
    h.hp = heroMaxHp();
    state.bossIn = CFG.boss.every;
    state.uiDirty = true;
    deathOverlay.classList.remove('show');
    logMsg('O Herói se levanta. Nível, atributos e itens mantidos — ouro e abates zerados.', 'good');
    logMsg('🏁 Run ' + state.runs + ': ' + runTitle(), 'lvl');
    spawnEnemy();
    renderAll();
    startBattle();
}

function newGame() {
    stopTimers();
    clearAutoRevive();
    autoReviveNote.hidden = true;
    state.hero = makeHero();
    state.hero.hp = heroMaxHp();
    state.over = false;
    state.runs = 1;
    state.bossIn = CFG.boss.every;
    state.stage = 1;
    state.uiDirty = true;
    deathOverlay.classList.remove('show');
    clearLog();
    logMsg('Uma nova jornada começa do zero.', 'good');
    logMsg('🏁 Run 1: ' + runTitle(), 'lvl');
    spawnEnemy();
    logMsg('A primeira criatura se aproxima: ' + state.enemy.name + '.', '');
    renderAll();
    startBattle();
}

function fullReset() {
    if (window.confirm('Recomeçar do zero? Apaga nível, atributos, itens, ouro e abates.')) {
        newGame();
    }
}

