        { n:'Cauda de Dragão', e:'🐉', hp:4, dmg:2, res:{ fis:15, arc:15, nec:0 } },
        { n:'Cauda-Folha', e:'🍂', hp:1, dmg:1, res:{ fis:0, arc:10, nec:0 } },
        { n:'Cauda-Sino', e:'🔔', hp:2, dmg:1, res:{ fis:15, arc:0, nec:0 } },
        { n:'Cauda Magnética', e:'🧲', hp:3, dmg:1, res:{ fis:0, arc:20, nec:0 } },
        { n:'Cauda-Abismo', e:'🕳️', hp:3, dmg:2, res:{ fis:0, arc:0, nec:30 } },
        { n:'Cauda de Vento', e:'🌪️', hp:2, dmg:2, res:{ fis:10, arc:10, nec:0 } },
        { n:'Cauda-Engrenagem', e:'⚙️', hp:3, dmg:1, res:{ fis:20, arc:0, nec:0 } },
        { n:'Cauda de Osso', e:'🦴', hp:3, dmg:1, res:{ fis:15, arc:0, nec:10 } },
        { n:'Cauda Sombria', e:'🌑', hp:2, dmg:2, res:{ fis:0, arc:0, nec:25 } }
    ]
};

function clampRes(v) {
    return Math.max(0, Math.min(60, v));
}

function monsterName(boss) {
    const base = randomPick(NAME_PREFIX) + ' ' + randomPick(NAME_SUFFIX);
    return boss ? randomPick(BOSS_TITLES) + ' ' + base : base;
}

function assembleMonster(monsterLevel, isBoss) {
    const head = randomPick(PARTS.heads);
    const torso = randomPick(PARTS.torsos);
    const limbs = randomPick(PARTS.limbs);
    const tail = Math.random() < 0.6 ? randomPick(PARTS.tails) : null;

    const baseHp = head.hp + torso.hp + limbs.hp + (tail ? tail.hp : 0);
    const baseDmg = head.dmg + torso.dmg + limbs.dmg + (tail ? tail.dmg : 0);
    const res = {
        fis: clampRes(head.res.fis + (tail ? tail.res.fis : 0)),
        arc: clampRes(head.res.arc + (tail ? tail.res.arc : 0)),
        nec: clampRes(head.res.nec + (tail ? tail.res.nec : 0))
    };

    const hpMult = CFG.enemy.hpMult(monsterLevel) * (isBoss ? CFG.boss.hpMult : 1);
    const dmgMult = CFG.enemy.dmgMult(monsterLevel) * (isBoss ? CFG.boss.dmgMult : 1);
    const maxHp = Math.round(baseHp * hpMult);

    return {
        name: monsterName(isBoss),
        level: monsterLevel,
        boss: isBoss,
        size: monsterSizeTier(monsterLevel, isBoss),
        pose: randomPick(POSES),
        el: torso.el,
        head: head, torso: torso, limbs: limbs, tail: tail,
        legs: limbs.legs,
        maxHp: maxHp,
        hp: maxHp,
        dmg: Math.max(1, Math.round(baseDmg * dmgMult)),
        res: res
    };
}

function spawnEnemy() {
    const isBoss = state.bossIn <= 0;
    // Monstros comuns ficam no nível da área (stage). Níveis maiores só
    // desbloqueiam após a derrota do boss daquele nível. Bosses podem ser
    // de até 2 níveis acima da área.
    const monsterLevel = isBoss
        ? state.stage + (Math.random() < 0.5 ? 1 : 2)
        : state.stage;
    const e = assembleMonster(monsterLevel, isBoss);
    e.xp = Math.round(CFG.enemy.xp(monsterLevel) * (isBoss ? CFG.boss.xpMult : 1));
    e.gold = Math.round(CFG.enemy.gold(monsterLevel) * (isBoss ? CFG.boss.goldMult : 1));
    state.enemy = e;
    if (isBoss) {
        state.bossIn = CFG.boss.every;
        logMsg('⚠ Um BOSS bloqueia o caminho: ' + e.name + '!', 'lvl');
    }
}

