// ===== Itens, drops e equipamento =====
const ITEM_SLOTS = [
    { id:'arma',     label:'Arma',     emoji:'⚔️', bonus:['fis','forca'] },
    { id:'armadura', label:'Armadura', emoji:'🛡️', bonus:['def','vida'] },
    { id:'elmo',     label:'Elmo',     emoji:'🪖', bonus:['vida','agil'] },
    { id:'colar',    label:'Colar',    emoji:'📿', bonus:['arc','int'] }
];

const STAT_LABEL = {
    fis: 'Dano Físico', arc: 'Dano Arcano', def: 'Defesa',
    forca: 'Força', int: 'Inteligência', agil: 'Agilidade', vida: 'Vida'
};

const ITEM_BASES = {
    arma:     ['Espada','Machado','Adaga','Lança','Machadinha','Cimitarra','Clava','Foice'],
    armadura: ['Cota de Malha','Placas de Ferro','Manto de Pele','Couraça','Égide','Brâmade'],
    elmo:     ['Elmo de Guerra','Baciamarta','Coroa de Ferro','Capuz','Barguilho','Mitrão'],
    colar:    ['Amuleto','Terço','Medalhão','Gargantilha','Pendente','Colar de Runas']
};

const ITEM_SUFFIX = ['do Viajante','das Brumas','de Ferro','da Meia-Noite','do Dragão','da Tempestade','do Abismo','de Ouro','do Pântano','da Lua','das Cinzas','do Trovão'];

function describeBonus(bonus) {
    return Object.keys(bonus).map(k => '+' + bonus[k] + ' ' + (STAT_LABEL[k] || k)).join(', ');
}

function makeItem(tier, heroLevel, boss) {
    const slot = randomPick(ITEM_SLOTS);
    const name = randomPick(ITEM_BASES[slot.id]) + ' ' + randomPick(ITEM_SUFFIX);
    const mult = CFG.tierMult[tier] * (boss ? CFG.boss.buff : 1);
    const scale = 1 + (heroLevel - 1) * 0.4;
    const bonus = {};
    slot.bonus.forEach((stat, i) => {
        const base = i === 0 ? 2 + heroLevel : 1 + Math.round(heroLevel * 0.6);
        bonus[stat] = Math.max(1, Math.round(base * mult * scale));
    });
    return { id: Math.random().toString(36).slice(2, 9), slot: slot.id, name: name, tier: tier, bonus: bonus };
}

function rollDrop(enemy, heroLevel) {
    if (enemy.boss) {
        return makeItem(randomPick(CFG.drops.bossTiers), heroLevel, true);
    }
    if (Math.random() < CFG.drops.commonChance) {
        return makeItem(randomPick(CFG.drops.commonTiers), heroLevel, false);
    }
    return null;
}

function equipItem(invIndex) {
    const h = state.hero;
    const item = h.inv[invIndex];
    if (!item) return;
    const current = h.equip[item.slot];
    h.inv.splice(invIndex, 1);
    h.equip[item.slot] = item;
    if (current) h.inv.push(current);
    h.hp = Math.min(h.hp, heroMaxHp());
    logMsg('Equipado: ' + item.name + '.', 'drop');
    state.uiDirty = true;
    renderAll();
}

function unequipItem(slotId) {
    const h = state.hero;
    const item = h.equip[slotId];
    if (!item) return;
    h.equip[slotId] = null;
    h.inv.push(item);
    h.hp = Math.min(h.hp, heroMaxHp());
    logMsg('Removido: ' + item.name + '.', 'drop');
    enforceInvLimit();
    state.uiDirty = true;
    renderAll();
}

// ===== Venda de itens =====
function itemSellValue(item) {
    let v = 0;
    Object.keys(item.bonus).forEach(k => { v += item.bonus[k]; });
    return v * CFG.sell.perBonus + CFG.sell.tierBonus[item.tier];
}

function sellItem(invIndex) {
    const h = state.hero;
    const item = h.inv[invIndex];
    if (!item) return;
    const value = itemSellValue(item);
    h.inv.splice(invIndex, 1);
    h.gold += value;
    logMsg('Vendido: ' + item.name + ' (+' + value + ' ouro).', 'drop');
    state.uiDirty = true;
    renderAll();
}

// Mochila limitada: ao passar do limite, vende o item MAIS ANTIGO da mochila.
// Itens equipados nunca são vendidos/trocados automaticamente.
function enforceInvLimit() {
    const h = state.hero;
    while (h.inv.length > CFG.invLimit) {
        const item = h.inv.shift(); // índice 0 = mais antigo
        const value = itemSellValue(item);
        h.gold += value;
        logMsg('Mochila cheia (' + CFG.invLimit + ' itens): ' + item.name + ' vendido automaticamente (+' + value + ' ouro).', 'drop');
    }
}

