// ===== Sprites (preparação para a arte futura) =====
// Tamanhos que um monstro pode ter, do menor ao maior.
const SPRITE_SIZES = ['pequeno', 'medio', 'grande', 'enorme', 'colossal'];

const SIZE_LABELS = {
    pequeno: 'Pequeno', medio: 'Médio', grande: 'Grande',
    enorme: 'Enorme', colossal: 'Colossal'
};

// Prefixo CSS usado para escalar a figura por tamanho.
const SIZE_PREFIX = {
    pequeno: 'peq', medio: 'med', grande: 'gra', enorme: 'eno', colossal: 'col'
};

// Tamanho com base no nível do monstro (bosses entram 1 tamanho acima).
function monsterSizeTier(level, isBoss) {
    const t = level + (isBoss ? 3 : 0);
    if (t >= 30) return 'colossal';
    if (t >= 20) return 'enorme';
    if (t >= 12) return 'grande';
    if (t >= 6)  return 'medio';
    return 'pequeno';
}

// ===== Registro de sprites (preencher quando a arte chegar) =====
// Estrutura por slot: SPRITES[slot][nomeDaParte][tamanho] = 'caminho da imagem'.
// Slots: head, torso, limbs, tail.
// Use '*' como fallback de tamanho quando não houver o tamanho específico.
// Exemplo:
//   SPRITES.head['Chifres Gêmeos'] = {
//       pequeno: 'img/sprites/chifres-p.png',
//       '*': 'img/sprites/chifres.png'
//   };
const SPRITES = {
    head:  {},
    torso: {},
    limbs: {},
    tail:  {}
};

// Retorna a URL do sprite para a parte + tamanho, ou null (→ fallback de emoji).
function spriteUrl(partKey, partName, size) {
    const slot = SPRITES[partKey];
    if (!slot) return null;
    const entry = slot[partName];
    if (!entry) return null;
    return entry[size] || entry['*'] || null;
}

